import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'marketingIndex',
  inject: ['reload'],
  data () {
    return {
      // 任务Id
      taskId: 0,
      echarts: '',
      marketingData: '',
      tableDataDB: '',
      tableData: [],
      settingData: '',
      MarketingStep: [],
      task: '',
      tab: { activeName: 'table' },
      table: [],
      spiderOption: '',
      selectionData: []
    }
  },
  methods: {
    ...mapActions([
      'dispatchCrawMarketingDataTest',
      'dispatchPushLogDataTest',
      'dispatchUpdateMarketingDataTest',
      'dispatchMarketingStepTest',
      'dispatchEchartTest',
      'dispatchDeleteMarketingDataTest',
      'dispatchCurrentTaskIdTest',
      'dispatchCompletedNumberTest',
      'dispatchContactSortTest',
      'dispatchContactReorderTest'
    ]),

    /**
   * @author: vince.Liang
   * @function: 数据初始化
   * @param none
   * @return:undefined
   */
    init () {
      this.taskId = Number(this.$route.params.id)
      // vuex没有当前任务id就注册监听事件
      if (this.judgeTaskIdTest(this.taskId)) {
        // 监听任务数据插入
        this.$socket.on('insertTaskData' + this.taskId, e => {
          this.dispatchCrawMarketingDataTest(e.detail)
          this.task.ContactNumber < this.tableDataDB.length && this.task.ContactNumber++
        })
        // 监听任务日志数据返回
        this.$socket.on('insertLog' + this.taskId, e => {
          this.dispatchPushLogDataTest(e.detail)
        })
        // 监听修改任务数据返回
        this.$socket.on('updateTaskData' + this.taskId, e => {
          this.dispatchUpdateMarketingDataTest(e.detail)
        })
        // 监听修改任务状态，主要在爬虫操作向营销操作过渡时触发
        // status  0(爬虫初始化),1(采集中),2(采集暂停),3(采集完成) 4(营销中) 5(营销暂停) 6(营销完成)
        this.$socket.on('updateTaskStatus' + this.taskId, e => {
          if (e.detail.Data.Status === 3) {
            this.$notify({
              title: this.$t('marketing.notifyTipTitle'),
              message: this.$t('marketing.initCrawlComplete'),
              type: 'success',
              duration: 0
            })
          }
          if (e.detail.Data.Status === 9 && this.task.Status !== 9) {
            this.$notify({
              title: this.$t('marketing.notifyTipTitle'),
              message: this.$t('marketing.depthCrawlComplete'),
              type: 'success',
              duration: 0
            })
          }
          if (e.detail.Data.Msg) {
            this.$WmlMsg(e.detail.Data.Msg, 'warning')
          }
          this.changeTaskStatusTest(e.detail.Data.TaskId, e.detail.Data.Status)
        })
        // 监听营销数据返回
        this.$socket.on('marketData' + this.taskId, e => {
          this.dispatchMarketingStepTest(e.detail)
        })
        // 监听图表数据返回
        this.$socket.on('updateChart' + this.taskId, e => {
          this.dispatchEchartTest(e.detail)
          if (e.detail.Data.TaskId === Number(this.$route.params.id)) {
            this.initEchart()
          }
        })
        // 删除数据
        this.$socket.on('deleteTaskData' + this.taskId, e => {
          this.dispatchDeleteMarketingDataTest(e.detail)
        })
        // 监听任务完成数量返回
        this.$socket.on('taskCompleted' + this.taskId, e => {
          this.dispatchCompletedNumberTest(e.detail)
        })
        // 任务排序
        this.$socket.on('contactSort' + this.taskId, e => {
          this.dispatchContactSortTest(e.detail)
          // console.log(e)
          // console.log('任务排序')
        })
        // 实时排序
        this.$socket.on('contactReorder' + this.taskId, e => {
          this.dispatchContactReorderTest(e.detail)
        })
      }
      // console.log(this.getterMarketingDataTest(this.taskId))
      // console.log('-------------------------------')
      this.marketingData = this.getterMarketingDataTest(this.taskId)
      // console.log(this.marketingData)
      // console.log('-------------------------------')
      // this.tableDataDB = this.getterTaskTableTest(this.taskId)
      // this.settingData = this.getterSettingDataTest(this.taskId)
      // this.task = this.getterTaskTest(this.taskId)
      // this.MarketingStep = this.getterMarketingStepTest(this.taskId)
      // this.spiderOption = this.getterSpiderOptionTest(this.taskId)
    }

